input.command:
$ava = 'D:\.1 Work Stations\RootMC\Web Files\rootmc-ava'
$script = @'
import { loadEnv } from "./src/config.mjs";
import { storePaths, setHushed, writeHeartbeat, pushStatusEvent } from "./src/store.mjs";
import { clearAsleep, isAsleep } from "./src/sleepMode.mjs";
import { clearPoweredOff, isPoweredOff } from "./src/powerDown.mjs";
import { clearCloudDark, isCloudDark } from "./src/cloudDark.mjs";
import { refreshEcoFlow, loadEcoSnapshot } from "./src/ecoflow.mjs";
import { buildHostSiteHourlyBlock, pushHostSiteTelemetry } from "./src/hostSite.mjs";

const env = await loadEnv();
storePaths();

const before = {
  asleep: isAsleep(),
  poweredOff: isPoweredOff(),
  cloudDark: isCloudDark(),
};
console.log("before", before);

clearAsleep("operator storage-farewell soft wake");
clearPoweredOff();
clearCloudDark("operator storage-farewell soft wake");
setHushed(false, "storage-farewell wake");
writeHeartbeat({ live: true, mode: "hot", asleep: false, poweredOff: false });
pushStatusEvent("soft wake · storage farewell ops");

console.log("after", { asleep: isAsleep(), poweredOff: isPoweredOff(), cloudDark: isCloudDark() });

console.log("refreshing EcoFlow…");
const snap = await refreshEcoFlow();
console.log("eco", {
  status: snap?.status,
  batteryPct: snap?.batteryPct,
  solarW: snap?.solarW ?? snap?.totals?.solarW,
  outW: snap?.outW ?? snap?.totals?.outW,
  inW: snap?.inW ?? snap?.totals?.inW,
  note: String(snap?.note || "").slice(0, 200),
  ageMs: snap?.at ? Date.now() - snap.at : null,
  devices: (snap?.devices || snap?.perSn || []).length || Object.keys(snap?.perSn || {}).length,
});

const block = await buildHostSiteHourlyBlock(env);
const push = await pushHostSiteTelemetry(env, block.payload);
console.log("host-site push", push);
console.log("weather", block.payload?.weather?.period?.short, block.payload?.weather?.period?.temp);
console.log("solar bank", block.payload?.solar?.batteryPct);
'@
Set-Content -Path "$ava\_tmp_wake_solar.mjs" -Value $script -Encoding UTF8
cd $ava
node _tmp_wake_solar.mjs
Remove-Item "$ava\_tmp_wake_solar.mjs" -Force -ErrorAction SilentlyContinue
# mirror clear on E twin data
$eData='E:\.1 Work Stations\RootMC\Server Handoffs\Ava Ivy\data'
if (Test-Path $eData) {
  if (Test-Path "$eData\power-off.json") { Remove-Item "$eData\power-off.json" -Force }
  '{"dark":false,"reason":"operator storage-farewell soft wake (E mirror)","by":"clear","updatedAt":' + [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds() + '}' | Set-Content "$eData\cloud-dark.json" -Encoding UTF8
  Write-Output 'E twin power-off cleared + cloud-dark mirrored'
}

$urls = @(
  'https://rootmc.net',
  'https://api.rootmc.net',
  'https://api.rootmc.net/api/rootmc/solar-mining-multiplier',
  'https://app.rootmc.net',
  'https://map.rootmc.net',
  'https://ava.rootmc.net',
  'https://ava.rootmc.net/solar',
  'https://ava.rootmc.net/api/status',
  'http://127.0.0.1:8787/api/status',
  'http://127.0.0.1:8787/solar',
  'https://play.rootmc.net'
)
foreach ($u in $urls) {
  $sw = [System.Diagnostics.Stopwatch]::StartNew()
  try {
    $r = Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 12 -MaximumRedirection 5
    $sw.Stop()
    Write-Output ("OK  {0,-12} {1}ms  {2}" -f $r.StatusCode, $sw.ElapsedMilliseconds, $u)
  } catch {
    $sw.Stop()
    $code = $null
    if ($_.Exception.Response) { $code = [int]$_.Exception.Response.StatusCode }
    Write-Output ("FAIL {0,-12} {1}ms  {2}  :: {3}" -f $(if($code){$code}else{'ERR'}), $sw.ElapsedMilliseconds, $u, $_.Exception.Message)
  }
}

$ErrorActionPreference='Continue'
# richer solar + mining + api health
try {
  $m = (Invoke-WebRequest 'https://api.rootmc.net/api/rootmc/solar-mining-multiplier' -UseBasicParsing -TimeoutSec 10).Content | ConvertFrom-Json
  Write-Output '=== mining mult ==='
  $m | ConvertTo-Json -Depth 4 -Compress
} catch { Write-Output "mining FAIL $_" }
try {
  $s = (Invoke-WebRequest 'http://127.0.0.1:8787/api/solar?hours=1' -UseBasicParsing -TimeoutSec 10).Content | ConvertFrom-Json
  Write-Output '=== solar live after refresh ==='
  [pscustomobject]@{
    batteryPct=$s.live.batteryPct; mood=$s.live.mood; solarW=$s.live.solarW; outW=$s.live.outW; inW=$s.live.inW
    ecoStatus=$s.live.ecoStatus; ecoAgeMs=$s.live.ecoAgeMs; ecoStale=$s.live.ecoStale
    morningAvgW=$s.live.morningAvgW; dayWh=$s.stats.solar.dayWh; weather=$s.weather.period.short
    devices=($s.live.devices | ForEach-Object { "$($_.label): soc=$($_.soc) solar=$($_.solarW)W out=$($_.outW)W ok=$($_.ok)" }) -join ' | '
  } | Format-List
} catch { Write-Output "solar FAIL $_" }
# claims/towny public probes
foreach ($u in @('https://api.rootmc.net/health','https://api.rootmc.net/api/health','https://rootmc.net/claims','https://rootmc.net/towny','https://map.rootmc.net/')) {
  try {
    $r = Invoke-WebRequest $u -UseBasicParsing -TimeoutSec 8
    Write-Output ("OK  {0} {1}" -f $r.StatusCode, $u)
  } catch {
    $code=$null; if ($_.Exception.Response){$code=[int]$_.Exception.Response.StatusCode}
    Write-Output ("FAIL {0} {1}" -f $(if($code){$code}else{'ERR'}), $u)
  }
}
